import React, { useState } from 'react';
import { motion } from 'framer-motion';

const certifications = [
  { name: 'Introduction to Python Programming', file: `${process.env.PUBLIC_URL}/assets/Intro_Python_prgm.pdf`, issuer: 'Coursera' },
  { name: 'Introduction to HTML',               file: `${process.env.PUBLIC_URL}/assets/Intro_to_HTML.pdf`,     issuer: 'Coursera' },
  { name: 'Introduction to Python',             file: `${process.env.PUBLIC_URL}/assets/Introduction_to_py.pdf`,issuer: 'Coursera' },
  { name: 'Prompt Engineering',                 file: `${process.env.PUBLIC_URL}/assets/Prompt_Enginnering_Linkedin.pdf`, issuer: 'LinkedIn Learning' },
];

const containerVariants = {
  hidden: {},
  show: { transition: { staggerChildren: 0.1 } },
};

const itemVariants = {
  hidden: { opacity: 0, x: -24 },
  show: { opacity: 1, x: 0, transition: { duration: 0.4, ease: 'easeOut' } },
};

const Certifications = () => {
  const [selectedCert, setSelectedCert] = useState(null);

  return (
    <motion.section
      className="certifications-section"
      initial="hidden"
      whileInView="show"
      viewport={{ once: true, amount: 0.15 }}
      variants={containerVariants}
    >
      <h2>Certifications</h2>
      <ul className="certifications-list">
        {certifications.map((cert) => (
          <motion.li key={cert.name} className="certification-item" variants={itemVariants}>
            <div className="cert-info">
              <span className="cert-issuer">{cert.issuer}</span>
              <button
                className="certification-button"
                onClick={() => setSelectedCert(selectedCert === cert.file ? null : cert.file)}
              >
                {cert.name}
              </button>
            </div>
            <span className="cert-arrow">{selectedCert === cert.file ? '▲' : '▼'}</span>
          </motion.li>
        ))}
      </ul>
      {selectedCert && (
        <motion.div
          className="pdf-preview"
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.3 }}
        >
          <h3>Certificate Preview</h3>
          <iframe src={selectedCert} title="Certificate Preview" className="pdf-embed" />
        </motion.div>
      )}
    </motion.section>
  );
};

export default Certifications;
